def _is_internal_module(module):
    """Signal whether the module is an internal CPython implementation detail."""
    return module in {'importlib', '_frozen_importlib', '_frozen_importlib_external',
                      '_warnings', 'warnings', '_thread'}


def _is_module_to_skip(module, skip_file_prefixes):
    """Signal whether the module is an internal CPython implementation detail."""
    return any(module.startswith(prefix) for prefix in skip_file_prefixes)


